bool FieldEquipmentData::load_file(const char*name,std::string&e){if(!name)return reject(e,"Field equipment path missing");FILE*f=std::fopen(name,"rb");if(!f)return reject(e,"Field equipment file unavailable");std::vector<uint8_t>b;uint8_t block[4096];bool ok=true;for(;;){auto n=std::fread(block,1,sizeof block,f);if(b.size()+n>2*1024*1024){ok=false;break;}b.insert(b.end(),block,block+n);if(n<sizeof block){ok=!std::ferror(f);break;}}if(std::fclose(f))ok=false;if(!ok)return reject(e,"Field equipment file read rejected");return load(b.data(),b.size(),e);}
